import { isObject, parseFrontmatter } from '@mintlify/common';
import fse from 'fs-extra';
import { readContainedMarkdown } from '../docsConfig/generateSdkDivisions.js';
const SDK_SCAN_CONCURRENCY = 16;
function collectNavigationPageSlugs(value, slugs = new Set()) {
    if (typeof value === 'string') {
        slugs.add(value.replace(/^\//, '').replace(/\.mdx?$/, ''));
        return slugs;
    }
    if (Array.isArray(value)) {
        value.forEach((entry) => collectNavigationPageSlugs(entry, slugs));
        return slugs;
    }
    if (!isObject(value))
        return slugs;
    if ('root' in value)
        collectNavigationPageSlugs(value.root, slugs);
    if ('pages' in value)
        collectNavigationPageSlugs(value.pages, slugs);
    if ('groups' in value)
        collectNavigationPageSlugs(value.groups, slugs);
    for (const key of ['tabs', 'anchors', 'dropdowns', 'versions', 'languages', 'products', 'menu']) {
        if (key in value)
            collectNavigationPageSlugs(value[key], slugs);
    }
    return slugs;
}
export async function scanSdkFrontmatterMetadata(contentDirectoryPath, navigation, pageScans) {
    const contentRoot = await fse.realpath(contentDirectoryPath);
    const metadataBySlug = {};
    const slugs = collectNavigationPageSlugs(navigation);
    const queue = slugs.values();
    await Promise.all(Array.from({ length: Math.min(SDK_SCAN_CONCURRENCY, slugs.size) }, async () => {
        for (const slug of queue) {
            try {
                const file = await readContainedMarkdown(contentRoot, slug, pageScans);
                if (file === undefined)
                    continue;
                const { attributes } = parseFrontmatter(file.content);
                if (attributes.sdk !== undefined) {
                    metadataBySlug[slug] = { sdk: attributes.sdk };
                }
            }
            catch {
                // Ignore unreadable/invalid frontmatter during the scan.
            }
        }
    }));
    return metadataBySlug;
}
